alter table public.online_presence drop constraint online_presence_location_check;
alter table public.online_presence add check(location in('town','warehouse','dungeon'));
alter table public.online_catalog add column def_bonus integer not null default 0;
create table public.online_adventure_config(id text primary key,data jsonb not null);
create table public.online_adventure_rooms(id uuid primary key default gen_random_uuid(),name text not null check(char_length(name) between 1 and 30),creator uuid not null references public.online_characters(id),password_hash bytea,status text not null default 'active' check(status in('active','cleared','abandoned')),snapshot jsonb not null,last_tick timestamptz not null default now(),created_at timestamptz not null default now());
create table public.online_adventure_members(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.online_adventure_rooms(id),character_id uuid not null references public.online_characters(id) on delete cascade,x integer not null default 5,y integer not null default 14,floor integer not null default 1,attack_at timestamptz not null default 'epoch',dir text not null default 'down',finished_at timestamptz,joined_at timestamptz not null default now(),unique(room_id,character_id));
create unique index online_one_adventure on public.online_adventure_members(character_id) where finished_at is null;
create table public.online_adventure_loot(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.online_adventure_rooms(id),floor integer not null,x integer not null,y integer not null,kind text not null,category text not null,amount integer,equipment_state jsonb);
create table public.online_adventure_rewards(room_id uuid references public.online_adventure_rooms(id),character_id uuid references public.online_characters(id),primary key(room_id,character_id));
create table public.online_adventure_attempts(user_id uuid primary key references auth.users(id),started_at timestamptz not null default now(),attempts integer not null default 0);
alter table public.online_adventure_config enable row level security;alter table public.online_adventure_rooms enable row level security;alter table public.online_adventure_members enable row level security;alter table public.online_adventure_loot enable row level security;alter table public.online_adventure_rewards enable row level security;alter table public.online_adventure_attempts enable row level security;
