create function public.online_adventure_blocked(px integer,py integer,f integer,s jsonb) returns boolean language plpgsql stable set search_path=public,pg_temp as $$
declare cfg jsonb;g jsonb;p jsonb;
begin
 if f=2 then return px<1 or py<1 or px>11 or py>9;end if;
 select data into cfg from online_adventure_config where id='floor1';
 if px<0 or py<0 or px>=88 or py>=34 or substring(cfg->'rows'->>py from px+1 for 1)<>'.' then return true;end if;
 for g in select jsonb_array_elements(cfg->'gates') loop if not(s->'keys' ? (g->>'key')) and px>=(g->>'x')::int and px<(g->>'x')::int+(g->>'w')::int and py>=(g->>'y')::int and py<(g->>'y')::int+(g->>'h')::int then return true;end if;end loop;
 for p in select jsonb_array_elements(cfg->'props') loop if px=(p->>'x')::int and py=(p->>'y')::int then return true;end if;end loop;return false;
end$$;
create function public.online_adventure_defence(cid uuid) returns integer language sql stable security definer set search_path=public,pg_temp as $$select coalesce(sum(t.def_bonus),0)::int from online_characters c cross join unnest(array['armor','shield','necklace']) slots(kind) join online_catalog t on t.key=case when slots.kind='armor' then 'armor_'||(c.gear->>(slots.kind||'_key')) else c.gear->>(slots.kind||'_key') end where c.id=cid and coalesce((c.gear->>slots.kind)::boolean,false)$$;
create function public.online_adventure_tick(rid uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare room public.online_adventure_rooms;s jsonb;enemies jsonb;enemy jsonb;m public.online_adventure_members;tele jsonb;danger jsonb:='[]';nx integer;ny integer;dist integer;i integer;phase integer;targetx integer;targety integer;step integer;warn jsonb;
begin
 select * into room from online_adventure_rooms where id=rid for update;
 if room.status<>'active' or room.last_tick>clock_timestamp()-interval '750 milliseconds' then return;end if;
 if not exists(select 1 from online_adventure_members a join online_presence p on p.character_id=a.character_id where a.room_id=rid and a.finished_at is null and a.floor=1 and p.location='dungeon' and p.seen_at>clock_timestamp()-interval '3 seconds') then update online_adventure_rooms set last_tick=clock_timestamp() where id=rid;return;end if;
 s:=room.snapshot;enemies:=s->'enemies';phase:=coalesce((s->>'tick')::int,0);
 for tele in select jsonb_array_elements(coalesce(s->'telegraphs','[]')) loop
  for m in select a.* from online_adventure_members a join online_presence p on p.character_id=a.character_id where a.room_id=rid and a.finished_at is null and a.floor=1 and p.location='dungeon' and p.seen_at>clock_timestamp()-interval '3 seconds' loop
   if exists(select 1 from jsonb_array_elements(tele->'tiles') t where (t->>'x')::int=m.x and (t->>'y')::int=m.y) then update online_characters set hp=greatest(0,hp-greatest(2,(tele->>'damage')::int-public.online_adventure_defence(id))) where id=m.character_id;end if;
  end loop;
 end loop;
 for i in 0..jsonb_array_length(enemies)-1 loop
  enemy:=enemies->i;if (enemy->>'hp')::int<=0 then continue;end if;
  select a.* into m from online_adventure_members a join online_presence p on p.character_id=a.character_id join online_characters q on q.id=a.character_id where a.room_id=rid and a.finished_at is null and a.floor=1 and q.hp>0 and p.location='dungeon' and p.seen_at>clock_timestamp()-interval '3 seconds' order by abs(a.x-(enemy->>'x')::int)+abs(a.y-(enemy->>'y')::int) limit 1;
  if m.id is null then continue;end if;nx:=(enemy->>'x')::int;ny:=(enemy->>'y')::int;dist:=abs(m.x-nx)+abs(m.y-ny);
  if coalesce((enemy->>'boss')::boolean,false) and dist<=10 then
   if phase%4=0 or phase%4=2 then
    warn:='[]';if phase%4=0 then for targetx in m.x-1..m.x+1 loop for targety in m.y-1..m.y+1 loop if not public.online_adventure_blocked(targetx,targety,1,s) then warn:=warn||jsonb_build_array(jsonb_build_object('x',targetx,'y',targety));end if;end loop;end loop;
    else for step in -4..4 loop warn:=warn||jsonb_build_array(jsonb_build_object('x',nx+step,'y',ny),jsonb_build_object('x',nx,'y',ny+step));end loop;end if;
    danger:=danger||jsonb_build_array(jsonb_build_object('tiles',warn,'damage',case when (enemy->>'hp')::int<(enemy->>'max')::int/2 then 22 else 16 end,'name',case when phase%4=0 then '結晶落下' else '十字の裂光' end));
   end if;
  elsif dist<=1 then update online_characters set hp=greatest(0,hp-greatest(1,(enemy->>'atk')::int-public.online_adventure_defence(id))) where id=m.character_id;
  elsif dist<=7 then
   if abs(m.x-nx)>abs(m.y-ny) then nx:=nx+sign(m.x-nx);else ny:=ny+sign(m.y-ny);end if;
   if not public.online_adventure_blocked(nx,ny,1,s) and not exists(select 1 from jsonb_array_elements(enemies) e where e->>'id'<>enemy->>'id' and (e->>'hp')::int>0 and (e->>'x')::int=nx and (e->>'y')::int=ny) and not exists(select 1 from online_adventure_members a join online_presence p on p.character_id=a.character_id where a.room_id=rid and a.floor=1 and a.finished_at is null and p.location='dungeon' and a.x=nx and a.y=ny) then enemy:=enemy||jsonb_build_object('x',nx,'y',ny);end if;
  end if;enemies:=jsonb_set(enemies,array[i::text],enemy);
 end loop;
 for m in select a.* from online_adventure_members a join online_characters q on q.id=a.character_id where a.room_id=rid and a.finished_at is null and q.hp<=0 loop
  select x,y into nx,ny from generate_series(3,10) gx(x) cross join generate_series(11,16) gy(y) where not exists(select 1 from online_adventure_members a join online_presence p on p.character_id=a.character_id where a.room_id=rid and a.character_id<>m.character_id and p.location='dungeon' and a.x=gx.x and a.y=gy.y) order by abs(x-5)+abs(y-14) limit 1;
  update online_adventure_members set x=coalesce(nx,5),y=coalesce(ny,14),floor=1 where id=m.id;update online_characters set hp=50 where id=m.character_id;
 end loop;
 update online_adventure_rooms set snapshot=s||jsonb_build_object('enemies',enemies,'tick',phase+1,'telegraphs',danger),last_tick=clock_timestamp() where id=rid;
end$$;
revoke all on function public.online_adventure_blocked(int,int,int,jsonb),public.online_adventure_defence(uuid),public.online_adventure_tick(uuid) from public,anon,authenticated;
alter function public.online_world(text,jsonb) rename to online_world_warehouse;
revoke all on function public.online_world_warehouse(text,jsonb) from public,anon,authenticated;
create function public.online_world(action text,payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare uid uuid:=auth.uid();c public.online_characters;pres public.online_presence;member public.online_adventure_members;room public.online_adventure_rooms;cfg jsonb;s jsonb;result jsonb;items jsonb;item jsonb;cat public.online_catalog;loot public.online_adventure_loot;a jsonb;enemy jsonb;events jsonb;logs jsonb;area text;keytext text;pass text;room_name text;rid uuid;nx integer;ny integer;dx integer;dy integer;i integer;j integer;n integer;idx integer;damage integer;reach integer;wx integer;wy integer;seq integer;count_members integer;kind text;equipment_slot text;attack_type text;hit boolean;was_inside boolean;body_hit boolean;checkpoint jsonb;
begin
 if uid is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,true) then raise exception 'メールアカウントでログインしてください。';end if;
 perform pg_advisory_xact_lock(71390119);perform pg_advisory_xact_lock(hashtextextended(uid::text,0));
 select * into pres from online_presence where user_id=uid;select * into c from online_characters where id=pres.character_id and user_id=uid;
 select * into member from online_adventure_members where character_id=c.id and finished_at is null;
 was_inside:=pres.location='dungeon';select data into cfg from online_adventure_config where id='floor1';
 if action like 'room_%' or was_inside then
  if c.id is null then raise exception '町に入場してください。';end if;
  if action='room_create' then
   if pres.location<>'town' then raise exception '町で部屋を作成してください。';end if;if member.id is not null then raise exception '参加中の冒険を再開するか、終了してください。';end if;
   room_name:=btrim(payload->>'name');pass:=coalesce(payload->>'password','');if room_name is null or char_length(room_name) not between 1 and 30 or room_name~'[[:cntrl:]]' or char_length(pass)>64 then raise exception '部屋名・合言葉を確認してください。';end if;
   rid:=gen_random_uuid();s:=jsonb_build_object('version',1,'enemies',cfg->'enemies','keys','[]'::jsonb,'opened','[]'::jsonb,'discovered','["entry"]'::jsonb,'tick',0,'telegraphs','[]'::jsonb,'events','[]'::jsonb,'seq',0,'stairs',false,'trapDisabled',false,'messages','[]'::jsonb);
   insert into online_adventure_rooms(id,name,creator,password_hash,snapshot) values(rid,room_name,c.id,case when pass<>'' then sha256(convert_to(rid::text||':'||pass,'UTF8')) end,s) returning * into room;
   insert into online_adventure_members(room_id,character_id) values(rid,c.id) returning * into member;
  elsif action='room_join' then
   if pres.location<>'town' then raise exception '町で部屋に参加してください。';end if;if member.id is not null then raise exception '別の冒険に参加中です。';end if;
   select * into room from online_adventure_rooms where id=(payload->>'room_id')::uuid for update;if room.id is null or room.status<>'active' then raise exception '参加できる部屋がありません。';end if;
   if room.password_hash is not null and room.password_hash<>sha256(convert_to(room.id::text||':'||coalesce(payload->>'password',''),'UTF8')) then raise exception '合言葉が違います。';end if;
   if (select count(*) from online_adventure_members where room_id=room.id and finished_at is null)>=4 then raise exception 'この部屋は満員です。';end if;
   insert into online_adventure_members(room_id,character_id) values(room.id,c.id) returning * into member;
  end if;
  if member.id is not null then select * into room from online_adventure_rooms where id=member.room_id for update;end if;s:=room.snapshot;
  if action in('room_enter','room_join','room_create','room_teleport') then
   if member.id is null or room.status='abandoned' then raise exception '参加中の冒険がありません。';end if;
   area:=coalesce(payload->>'area','entry');if area='current' then area:=null;nx:=member.x;ny:=member.y;
   else if not(s->'discovered' ? area) then raise exception 'まだ到達していないエリアです。';end if;if area='depth2' then nx:=5;ny:=8;else select value into a from jsonb_array_elements(cfg->'areas') where value->>'id'=area;nx:=(a->>'sx')::int;ny:=(a->>'sy')::int;end if;end if;
